import { useState } from "react";
import { Link, useRouter } from "@/router";
import { audiences, mainNav, quickLinks } from "@/data/site";
import { HomeIcon, SearchIcon } from "./Icons";

export function Header({ reportLabel }: { reportLabel: string }) {
  const { path } = useRouter();
  const [menuOpen, setMenuOpen] = useState(false);
  const [quickOpen, setQuickOpen] = useState(false);

  const isActive = (to: string) => {
    const base = to === "/" ? "/" : to;
    return to === "/" ? path === "/" : path === base;
  };

  return (
    <header className="relative z-30 bg-[rgba(0,50,106,0.80)]">
      <div className="mx-auto max-w-[1440px]">
        {/* Brand + utility bar */}
        <div className="relative">
          <h1 className="m-0 float-left">
            <Link
              to="/"
              className="brand-logo block h-[138px] w-[132px] bg-[#00274c] bg-[url('/skins/um2013/media/images/umich-logo.png')] bg-[length:100%_100%] indent-[-9000px]"
              style={{ textIndent: "-9000px" }}
            >
              Corravale University
            </Link>
          </h1>
          <div className="bg-[#003e78] py-[10px] text-right">
            <div className="inline-block align-top pr-[15px]">
              <Link
                to="/_404.html"
                className="relative inline-block rounded-[2px] bg-[#ffcb0b] px-[32px] py-[8px] text-[12px] leading-[15px] text-[#002c5a] no-underline transition-all duration-200 hover:bg-[#fddd67]"
              >
                <span>{reportLabel}</span>
                <span className="absolute right-[10px] top-1/2 -mt-[0.5em] text-[14px]">›</span>
              </Link>
            </div>
            <div className="inline-block align-top">
              <form
                role="search"
                className="relative text-right"
                onSubmit={(e) => {
                  e.preventDefault();
                  window.location.href = "/_404.html";
                }}
              >
                <label className="block">
                  <span className="hidden-label">Search for:</span>
                  <input
                    type="search"
                    placeholder="Search"
                    aria-label="Search for:"
                    className="w-[186px] rounded-[2px] border-none px-[10px] py-[8px] pr-[28px] font-[Roboto] text-[12px] outline-none"
                  />
                </label>
                <button
                  type="submit"
                  className="absolute right-[6px] top-1/2 -mt-[7px] -ml-[17px] cursor-pointer border-none bg-transparent p-0 text-[14px] text-black"
                >
                  <span className="hidden-label">Search</span>
                  <SearchIcon className="align-middle" />
                </button>
              </form>
            </div>
          </div>
        </div>

        {/* Audiences + quick links */}
        <div className="pt-[30px] font-['Roboto_Condensed'] font-bold tracking-[1px]">
          <div className="mx-auto flex max-w-[1200px] items-start justify-between px-[10px]">
            <nav aria-label="Audiences" className="ml-[30px] hidden w-[690px] text-[11px] uppercase lg:block">
              <ul className="m-0 flex list-none p-0">
                <li aria-hidden="true" className="border-y border-l border-[#567daa] bg-[#002c5a] px-[10px] py-[10px] text-[#ffcb0b]">
                  For:
                </li>
                {audiences.map((a) => (
                  <li
                    key={a.to}
                    className="border-y border-r border-[#567daa] bg-[#002c5a]"
                  >
                    <Link
                      to={a.to}
                      className="block px-[10px] py-[10px] text-[#ffcb0b] no-underline transition-all duration-200 hover:bg-[#0d57aa]"
                    >
                      {a.label}
                    </Link>
                  </li>
                ))}
              </ul>
            </nav>
            <details className="relative z-10 text-[12px]" open={quickOpen} onToggle={(e) => setQuickOpen((e.target as HTMLDetailsElement).open)}>
              <summary className="relative block w-[166px] cursor-pointer list-none rounded-[2px_3px_3px_2px] bg-[#ffcb0b] p-[10px] uppercase leading-none text-[#002c5a] transition-all duration-200">
                Quick Links
                <span className="absolute right-0 top-0 rounded-[0_2px_2px_0] bg-[#444] p-[4px] text-[16px] text-white">+</span>
              </summary>
              <nav aria-label="Quick Links" className="absolute right-0 w-[230px] border border-[#4b4b4b] bg-[#002c5a] p-[10px] shadow-lg">
                <ul className="m-0 list-none p-0 text-[12px] normal-case tracking-normal">
                  {quickLinks.map((q) => (
                    <li key={q.label} className="border-b border-dotted border-[#8e8c8c] last:border-b-0">
                      <Link to={q.to} className="block py-[6px] font-normal text-white no-underline hover:text-[#ffcb0b]">
                        <span className="hover:border-b hover:border-dotted hover:border-[#ffcb0b]">{q.label}</span>
                      </Link>
                    </li>
                  ))}
                </ul>
              </nav>
            </details>
          </div>
        </div>

        {/* Main nav */}
        <nav aria-label="Main Menu" className="clear-both mt-[10px] border-y border-[#567daa]">
          <div className="font-[Georgia,'Times_New_Roman',Times,serif] text-[16px]">
            <div className="lg:hidden">
              <button
                type="button"
                onClick={() => setMenuOpen((v) => !v)}
                className="flex w-full items-center justify-between bg-transparent px-[15px] py-[12px] text-white"
              >
                <span className="text-[16px] font-bold">Main Menu</span>
                <span className="text-[18px]">{menuOpen ? "×" : "≡"}</span>
              </button>
            </div>
            <ul
              className={`${menuOpen ? "block" : "hidden"} m-0 list-none border-r border-[#567daa] p-0 lg:flex`}
            >
              <li className="relative border-l border-[#567daa] text-center lg:flex-[0_0_5%]">
                <Link
                  to="/"
                  aria-current={isActive("/") ? "page" : undefined}
                  className={`group relative flex w-full items-center justify-center px-0 py-[10px] no-underline transition-all duration-200 ${
                    isActive("/") ? "bg-[#0d57aa] text-[#ffcb0b]" : "text-white"
                  }`}
                >
                  <span className="hidden-label">Home</span>
                  <HomeIcon className="h-[16px] w-[16px] group-hover:text-[#ffcb0b]" />
                </Link>
              </li>
              {mainNav.map((item) => (
                <li key={item.to} className="relative grow border-l border-[#567daa] text-center">
                  <Link
                    to={item.to}
                    aria-current={isActive(item.to) ? "page" : undefined}
                    className={`block w-full whitespace-nowrap px-[10px] py-[10px] no-underline transition-all duration-200 ${
                      isActive(item.to) ? "bg-[#0d57aa] text-[#ffcb0b]" : "text-white hover:text-[#ffcb0b]"
                    }`}
                  >
                    {item.label}
                  </Link>
                </li>
              ))}
            </ul>
          </div>
        </nav>
      </div>
    </header>
  );
}

import type { ReactNode } from "react";
import { Link } from "@/router";
import type { NavBlock } from "@/data/navGroups";
import { ChevronCircle } from "./Icons";

export function SectionHeading({ title, tone = "dark" }: { title: string; tone?: "dark" | "light" }) {
  return (
    <div
      className={`py-[20px] text-center text-[30px] uppercase tracking-[5px] ${
        tone === "dark" ? "text-white" : "text-[#3f6ea6]"
      }`}
    >
      <h2
        className={`m-0 border-b pb-[10px] text-[30px] font-normal font-['Roboto_Condensed'] ${
          tone === "dark" ? "border-white/70" : "border-[#3f6ea6]"
        }`}
      >
        {title}
      </h2>
    </div>
  );
}

/** One dark navigation block from a section landing page. */
export function NavBlockPanel({ block }: { block: NavBlock }) {
  return (
    <div className="min-h-[275px] rounded-[2px] border border-[#4b4b4b] bg-[#222222] p-[15px]">
      <h4 className="m-0 pb-[15px] text-[16px] font-bold uppercase text-[#72b4ff]">{block.title}</h4>
      <ul className="m-0 list-none p-0">
        {block.items.map((it, i) => (
          <li key={it.label + i} className={`relative py-[10px] ${i > 0 ? "border-t border-dotted border-[#8e8c8c]" : ""}`}>
            <Link
              to={it.to}
              className="cu-panel-link relative block pr-[25px] leading-[1.2em] tracking-[0.5px] text-white no-underline"
            >
              <span>{it.label}</span>
              {it.note ? <em className="block pt-[3px] text-[12px] not-italic leading-[1em] text-gray-300">{it.note}</em> : null}
              <ChevronCircle className="absolute right-0 top-0 text-[#ffcb0b]" />
            </Link>
          </li>
        ))}
      </ul>
    </div>
  );
}

export function LandingPanel({
  intro,
  groups,
  feature,
  heading,
  tone = "dark",
}: {
  intro: string;
  groups: NavBlock[];
  feature: { src: string; alt: string; caption: string };
  heading: string;
  tone?: "dark" | "light";
}) {
  return (
    <section className="bg-[#333333] pb-[30px]">
      <div className="mx-auto max-w-[1200px] px-[10px]">
        <SectionHeading title={heading} tone={tone} />
        <p className="mx-auto max-w-[1000px] px-[10px] text-center text-[14px] leading-[1.5] text-[#cfcfcf]">{intro}</p>
        <div className="mt-[20px] flex flex-wrap gap-[10px]">
          <div className="grid w-full grid-cols-1 gap-[10px] sm:grid-cols-2 lg:w-4/5 lg:grid-cols-3">
            {groups.map((g) => (
              <NavBlockPanel key={g.title} block={g} />
            ))}
          </div>
          <aside className="w-full lg:w-[19%]">
            <img src={feature.src} alt={feature.alt} className="block w-full" />
            <p className="mt-[6px] text-[14px] italic leading-[1.4] text-[#cfcfcf]">{feature.caption}</p>
          </aside>
        </div>
      </div>
    </section>
  );
}

export function PageIntro({ lead }: { lead: string }) {
  return (
    <p className="mx-auto max-w-[1000px] px-[10px] pt-[20px] text-center text-[16px] leading-[1.6] text-[#333]">{lead}</p>
  );
}

export function FeatureBanner({ src, alt, caption }: { src: string; alt: string; caption?: string }) {
  return (
    <section className="relative">
      <img src={src} alt={alt} className="block h-[440px] w-full object-cover" />
      {caption ? (
        <div className="absolute bottom-[30px] left-[10%] max-w-[300px] bg-[rgba(0,39,76,0.78)] p-[18px] text-[15px] italic leading-[1.4] text-white">
          <span className="mb-[6px] block text-right text-[12px] not-italic">^</span>
          {caption}
        </div>
      ) : null}
    </section>
  );
}

/** Vertical strip of gallery thumbnails used by "Seize Today" style sections. */
export function GalleryStrip({
  shots,
  columns,
  showTimes = true,
}: {
  shots: { src: string; alt: string; time: string }[];
  columns: number;
  showTimes?: boolean;
}) {
  return (
    <ul
      className="m-0 grid list-none gap-[10px] p-0"
      style={{ gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))` }}
    >
      {shots.map((s, i) => (
        <li key={i} className="relative cursor-pointer">
          <img src={s.src} alt={s.alt} className="block h-[110px] w-full object-cover" />
          {showTimes ? (
            <span className="absolute bottom-0 left-0 bg-[#00274c] px-[6px] py-[2px] text-[11px] text-white">{s.time}</span>
          ) : null}
        </li>
      ))}
    </ul>
  );
}

export function SubHeading({ children }: { children: ReactNode }) {
  return (
    <h3 className="py-[24px] text-center font-['Roboto_Condensed'] text-[34px] font-light uppercase tracking-[6px] text-[#3f6ea6]">
      {children}
    </h3>
  );
}

import { Link } from "@/router";
import { navGroups } from "@/data/navGroups";
import { GalleryStrip, GalleryStrip as _GalleryStrip } from "@/components/SectionBits";
import { ChevronCircle } from "@/components/Icons";
import { FeatureBanner, SectionHeading } from "@/components/SectionBits";
import { galleryFor } from "@/data/pages";

export interface SectionConfig {
  path: string;
  heading: string;
  intro: string;
  sideImage: string;
  sideCaption: string;
  featureImage: string;
  featureAlt: string;
  featureCaption: string;
  tone?: "dark" | "light";
  gallery?: "seize" | "student";
  galleryTitle?: string;
  galleryCopy?: string;
}

function NavBlockPanel({ title, items }: { title: string; items: { label: string; to: string; note?: string }[] }) {
  return (
    <div className="min-h-[275px] rounded-[2px] border border-[#4b4b4b] bg-[#222222] p-[15px]">
      <h4 className="m-0 pb-[15px] text-[16px] font-bold uppercase text-[#72b4ff]">{title}</h4>
      <ul className="m-0 list-none p-0">
        {items.map((it, i) => (
          <li key={it.label + i} className={`relative py-[10px] ${i > 0 ? "border-t border-dotted border-[#8e8c8c]" : ""}`}>
            <Link
              to={it.to}
              className="cu-panel-link relative block pr-[25px] leading-[1.2em] tracking-[0.5px] text-white no-underline"
            >
              <span>{it.label}</span>
              {it.note ? <em className="block pt-[3px] text-[12px] italic leading-[1em] text-gray-300">{it.note}</em> : null}
              <ChevronCircle className="absolute right-0 top-0 text-[#ffcb0b]" />
            </Link>
          </li>
        ))}
      </ul>
    </div>
  );
}

export function SectionPage({ config }: { config: SectionConfig }) {
  const groups = navGroups[config.path] ?? [];
  const gallery = config.gallery ? galleryFor(config.gallery) : null;

  return (
    <>
      <section className="bg-[#333333] pb-[30px]">
        <div className="mx-auto max-w-[1200px] px-[10px]">
          <SectionHeading title={config.heading} tone={config.tone} />
          <p className="mx-auto max-w-[1000px] px-[10px] text-center text-[14px] leading-[1.5] text-[#cfcfcf]">{config.intro}</p>
          <div className="mt-[20px] flex flex-wrap gap-[10px]">
            <div className="grid w-full grid-cols-1 gap-[10px] sm:grid-cols-2 lg:w-4/5 lg:grid-cols-3">
              {groups.map((g) => (
                <NavBlockPanel key={g.title} title={g.title} items={g.items} />
              ))}
            </div>
            <aside className="w-full lg:w-[19%]">
              <img src={config.sideImage} alt={config.featureAlt} className="block w-full" />
              <p className="mt-[6px] text-[14px] italic leading-[1.4] text-[#cfcfcf]">{config.sideCaption}</p>
            </aside>
          </div>
        </div>
      </section>

      <FeatureBanner src={config.featureImage} alt={config.featureAlt} caption={config.featureCaption} />

      {gallery ? (
        <section className="bg-white pb-[40px]">
          <div className="mx-auto max-w-[960px] px-[10px]">
            <h3 className="pb-[10px] pt-[26px] text-center font-['Roboto_Condensed'] text-[26px] font-normal uppercase tracking-[2px] text-[#4B4B4B]">
              {config.galleryTitle}
            </h3>
            <p className="mb-[20px] text-center font-['Roboto_Condensed'] text-[#757575]">{config.galleryCopy}</p>
            <GalleryStrip shots={gallery} columns={4} />
          </div>
        </section>
      ) : null}
    </>
  );
}

import type { ReactNode } from "react";
import type { GalleryShot } from "@/data/site";

export function SectionHeading({ title, tone = "dark" }: { title: string; tone?: "dark" | "light" }) {
  return (
    <div className="px-[10px] py-[20px] text-center text-[30px] uppercase tracking-[5px]">
      <h2
        className={`m-0 border-b pb-[10px] font-['Roboto_Condensed'] text-[30px] font-normal ${
          tone === "dark" ? "border-white/70 text-white" : "border-[#3f6ea6] text-[#3f6ea6]"
        }`}
      >
        {title}
      </h2>
    </div>
  );
}

export function FeatureBanner({ src, alt, caption }: { src: string; alt: string; caption?: string }) {
  return (
    <section className="relative">
      <img src={src} alt={alt} className="block h-[340px] w-full object-cover lg:h-[440px]" />
      {caption ? (
        <div className="absolute bottom-[30px] left-[10%] max-w-[300px] bg-[rgba(0,39,76,0.78)] p-[18px] text-[15px] italic leading-[1.4] text-white">
          <span className="mb-[6px] block text-right text-[12px] not-italic">^</span>
          {caption}
        </div>
      ) : null}
    </section>
  );
}

export function GalleryStrip({ shots, columns = 4 }: { shots: GalleryShot[]; columns?: number }) {
  const cls =
    columns === 4 ? "h-[152px] w-[152px]" : columns === 3 ? "h-[180px] w-[180px]" : "h-[140px] w-full";
  return (
    <ul className="m-0 list-none p-0 text-center">
      {shots.map((s, i) => (
        <li key={i} className={`group relative m-[4px_2px] inline-block overflow-hidden rounded-[2px] align-top ${cls}`}>
          <img
            src={s.src}
            alt={s.alt}
            className="absolute inset-0 m-auto h-full w-full object-cover transition-opacity duration-300 group-hover:opacity-60"
          />
          <span className="absolute bottom-0 left-0 block bg-black p-[4px] font-['Roboto_Condensed'] text-[0.8em] text-[#efefef]">
            {s.time}
          </span>
        </li>
      ))}
    </ul>
  );
}

export function Prose({ children }: { children: ReactNode }) {
  return <div className="mx-auto max-w-[900px] px-[10px] py-[20px] text-[16px] leading-[1.7] text-[#333]">{children}</div>;
}

import { Link } from "@/router";
import { privacyBlocks } from "@/data/privacy";
import { navGroups } from "@/data/navGroups";
import { contactLinks, contactRows } from "@/data/site";
import { ChevronCircle, MailIcon } from "@/components/Icons";
import { SectionHeading } from "@/components/SectionBits";

function PanelShell({
  title,
  tone = "dark",
  intro,
  children,
}: {
  title: string;
  tone?: "dark" | "light";
  intro?: string;
  children?: React.ReactNode;
}) {
  return (
    <>
      <div className="px-[10px] pt-[10px] text-center text-[15px] uppercase tracking-[6px]">
        <h2 className={`font-['Roboto_Condensed'] text-[30px] font-normal ${tone === "dark" ? "text-[#3f6ea6]" : "text-[#3f6ea6]"}`}>
          {title}
        </h2>
      </div>
      <hr className="mx-auto my-[10px] max-w-[1200px] border-[#9a9a9a]" />
      {intro ? (
        <p className="mx-auto max-w-[1100px] px-[10px] py-[10px] text-center text-[16px] leading-[1.6] text-[#333]">{intro}</p>
      ) : null}
      {children}
    </>
  );
}

export function SchoolsCollegesPage() {
  const groups = navGroups["/schools-colleges/"] ?? [];
  return (
    <div className="bg-white pb-[40px]">
      <div className="mx-auto max-w-[1200px]">
        <PanelShell
          title="Schools & Colleges"
          intro="Students discover their passions and chart their futures across our 19 nationally recognized schools and colleges — the heart and soul of the Corravale experience at our flagship campus. Meanwhile, our Corravale Westgate and Corravale Alden campuses offer inspiration and direction to more than 15,000 students."
        />
        <div className="flex flex-wrap gap-[10px] px-[10px]">
          {groups.map((g) => (
            <div key={g.title} className="w-full sm:w-[calc(50%-5px)] lg:w-[calc(33.333%-7px)]">
              <div className="h-full rounded-[2px] border border-[#e1e1e1] bg-[#f6f6f6] p-[15px]">
                <h4 className="m-0 border-b border-[#c9c9c9] pb-[10px] text-[16px] font-bold uppercase text-[#00274c]">{g.title}</h4>
                <ul className="m-0 list-none p-0">
                  {g.items.map((it, i) => (
                    <li key={it.label + i} className="py-[8px] text-[16px]">
                      <Link to={it.to} className="flex items-start justify-between gap-[8px] text-[#0d57aa] no-underline hover:underline">
                        <span>{it.label}</span>
                        <ChevronCircle className="mt-[3px] shrink-0 text-[#ffcb0b]" />
                      </Link>
                    </li>
                  ))}
                </ul>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

export function ContactPage() {
  return (
    <div className="bg-white pb-[40px]">
      <div className="mx-auto max-w-[1200px]">
        <PanelShell
          title="Contact Us"
          intro="Have a question but unsure where to start or whom to reach? To point you in the right direction, we've gathered some of the most frequently contacted Corravale departments in the table below. Should you not find the office tied to your particular need, please try our site search to locate the right resource."
        />
        <div className="px-[10px]">
          <h3 className="py-[16px] text-center text-[24px] font-normal text-[#00274c]">Most Frequently Reached Campus</h3>
          <table className="w-full border-collapse">
            <thead>
              <tr>
                <th className="border border-[#c9c9c9] bg-[#00274c] px-[12px] py-[10px] text-left text-[16px] text-white">Department</th>
                <th className="border border-[#c9c9c9] bg-[#00274c] px-[12px] py-[10px] text-left text-[16px] text-white">Phone</th>
              </tr>
            </thead>
            <tbody>
              {contactRows.map((r, i) => (
                <tr key={r.dept} className={i % 2 ? "bg-[#f4f6f9]" : "bg-white"}>
                  <td className="border border-[#c9c9c9] px-[12px] py-[10px] text-[16px] text-[#333]">
                    <span className="block text-[12px] uppercase text-[#777]">Department</span>
                    {r.dept}
                  </td>
                  <td className="border border-[#c9c9c9] px-[12px] py-[10px] text-[16px] text-[#333]">
                    {r.phone ? (
                      <>
                        <span className="block text-[12px] uppercase text-[#777]">Phone</span>
                        <a href={`tel:${r.phone}`} className="text-[#0d57aa] no-underline hover:underline">
                          {r.phone}
                        </a>
                      </>
                    ) : null}
                    {r.email ? (
                      <a href={`mailto:${r.email}`} className="mt-[4px] block text-[#0d57aa] no-underline hover:underline">
                        {r.email}
                      </a>
                    ) : null}
                    {r.chat ? (
                      <Link to="/_404.html" className="mt-[4px] block text-[#0d57aa] no-underline hover:underline">
                        <MailIcon className="mr-[5px] inline" />
                        {r.chat}
                      </Link>
                    ) : null}
                    {r.website ? (
                      <Link to="/_404.html" className="text-[#0d57aa] no-underline hover:underline">
                        {r.website}
                      </Link>
                    ) : null}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>

          <h3 className="py-[16px] text-[24px] font-normal text-[#00274c]">More Contact Options and Links</h3>
          <ul className="m-0 list-disc pl-[24px]">
            {contactLinks.map((l) => (
              <li key={l} className="py-[4px] text-[16px]">
                <Link to="/_404.html" className="text-[#0d57aa] no-underline hover:underline">
                  {l}
                </Link>
              </li>
            ))}
          </ul>

          <h3 className="py-[16px] text-[24px] font-normal text-[#00274c]">Mailing Addresses</h3>
